<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\{Patient,AdmissionRequest,CaregiverAccess,Notification,User};use Illuminate\Http\Request;
class WorkflowController extends Controller {
 public function requestAdmission(Request $r){$r->validate(['reason'=>'required|string|max:3000','symptoms'=>'nullable|array','symptoms.*'=>'string|max:100']);$p=$r->user()->patientProfile;if(!$p)return response()->json(['message'=>'Patient profile not found'],422);$a=$p->admissionRequests()->create(['reason'=>$r->reason,'symptoms'=>$r->symptoms??[]]);foreach(User::whereIn('role',['doctor','admin'])->get() as $u)Notification::create(['user_id'=>$u->id,'title'=>'New virtual admission request','body'=>$r->user()->name.' submitted admission request #'.$a->id]);return response()->json($a,201);}
 public function admissions(Request $r){$q=AdmissionRequest::with('patient.user','reviewer')->latest();if($r->user()->role==='patient')$q->whereHas('patient',fn($x)=>$x->where('user_id',$r->user()->id));elseif(!in_array($r->user()->role,['doctor','admin','specialist']))return response()->json([]);return $q->get();}
 public function reviewAdmission(Request $r,AdmissionRequest $admission){abort_unless(in_array($r->user()->role,['doctor','admin']),403);$d=$r->validate(['status'=>'required|in:approved,rejected,needs_information','review_note'=>'nullable|string|max:2000']);$admission->update($d+['reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);$patient=$admission->patient->user;Notification::create(['user_id'=>$patient->id,'title'=>'Virtual admission updated','body'=>'Your admission request #'.$admission->id.' is '.$d['status'].'.']);return $admission->fresh(['patient.user','reviewer']);}
 public function requestCaregiver(Request $r){$d=$r->validate(['patient_id'=>'required|exists:patients,id']);abort_unless($r->user()->role==='caregiver',403);$p=Patient::findOrFail($d['patient_id']);$link=CaregiverAccess::firstOrCreate(['patient_id'=>$p->id,'caregiver_id'=>$r->user()->id],['status'=>'pending']);return response()->json($link,201);}
 public function caregiverRequests(Request $r){abort_unless(in_array($r->user()->role,['admin','doctor']),403);return CaregiverAccess::with('patient.user','caregiver')->where('status','pending')->latest()->get();}
 public function reviewCaregiver(Request $r,CaregiverAccess $access){abort_unless(in_array($r->user()->role,['admin','doctor']),403);$d=$r->validate(['status'=>'required|in:approved,rejected']);$access->update($d+['approved_by'=>$r->user()->id]);Notification::create(['user_id'=>$access->caregiver_id,'title'=>'Caregiver access request updated','body'=>'Your access request is '.$d['status'].'.']);return $access->fresh(['patient.user','caregiver']);}
 public function myPatients(Request $r){abort_unless($r->user()->role==='caregiver',403);return CaregiverAccess::with('patient.user')->where('caregiver_id',$r->user()->id)->where('status','approved')->get()->pluck('patient');}
}
